import assert from 'node:assert/strict'
import {readFileSync} from 'node:fs'
import {DatabaseSync} from 'node:sqlite'
const app=readFileSync('src/App.tsx','utf8')
const header=readFileSync('src/features/sections/OrdersHeaderSection.tsx','utf8')
const filters=readFileSync('src/features/sections/OrderFiltersSection.tsx','utf8')
const table=readFileSync('src/features/sections/OrdersTableSection.tsx','utf8')
const create=readFileSync('src/features/sections/CreateOrderSection.tsx','utf8')
const workshop=readFileSync('src/features/sections/WorkshopSection.tsx','utf8')
const worker=readFileSync('worker/domains/orders-write.ts','utf8')
assert(!header.includes('openKaspiCreate'))
assert(!header.includes('Создать заказ'))
assert(!app.includes('activeSector === \'kaspi\' && orderPanel === \'zammler\''))
assert(!app.includes('confirmKaspiPayment('))
assert(!app.includes('submitKaspiPayment('))
assert(!app.includes('kaspiPaymentDraft'))
assert(!table.includes('Подтвердить оплату'))
assert(!table.includes('confirmKaspiPayment'))
assert(table.includes('markOrderSentToClient'))
assert(!filters.includes('Ожидают оплату'))
assert(app.includes("params.set('orderPaymentMethod', 'КАСПИ МАГАЗИН')"))
assert(app.includes("params.set('excludeOrderPaymentMethod', 'КАСПИ МАГАЗИН')"))
assert(workshop.includes("workshopChannel === 'kaspi'"))
assert(workshop.includes("'КАСПИ МАГАЗИН'"))
assert(create.includes('Полная сумма Kaspi магазин автоматически учитывается'))
assert(app.includes('receivedAmount: isKaspi ? createPricing.totalAmount ?? 0'))
assert(worker.includes("if (pricingMode !== 'itemized_v1')"))
assert(worker.includes("if (orderPaymentMethod === 'КАСПИ МАГАЗИН')"))
assert(worker.includes('const unbooked = buildItemizedOrderWritePlan(itemizedLines, [])'))
assert(worker.includes('normalizedPayments = normalizeOrderPayments([{'))
assert(worker.includes("method: 'КАСПИ МАГАЗИН'"))
assert(worker.includes('amount: unbooked.totalAmount'))
assert(worker.includes("paymentKind: 'primary'"))
assert(worker.includes('itemizedWritePlan = buildItemizedOrderWritePlan(itemizedLines, normalizedPayments)'))
assert(worker.includes('const existingPaymentId = await criticalOperationEntityId('))
assert(worker.includes('buildPaymentAndMoneyEventStatements'))
// A proper single, idempotent primary payment yields paid order with no debt;
// inserting it a second time is forbidden by unique operation identity.
const db=new DatabaseSync(':memory:')
db.exec("CREATE TABLE orders(id INTEGER PRIMARY KEY,total_amount INTEGER,received_amount INTEGER,debt_amount INTEGER);"+
 "CREATE TABLE payments(id INTEGER PRIMARY KEY,order_id INTEGER,request_key TEXT UNIQUE,method TEXT,amount INTEGER);"+
 "INSERT INTO orders VALUES(77,22500,22500,0)")
const pay=db.prepare("INSERT OR IGNORE INTO payments(order_id,request_key,method,amount) VALUES(77, 'create:77:primary:1','КАСПИ МАГАЗИН',22500)")
pay.run();pay.run()
assert.equal(db.prepare('SELECT COUNT(*) AS n FROM payments WHERE order_id=77').get().n,1)
assert.equal(db.prepare('SELECT received_amount FROM orders WHERE id=77').get().received_amount,22500)
assert.equal(db.prepare('SELECT debt_amount FROM orders WHERE id=77').get().debt_amount,0)
db.close()
console.log('KASPI_PAID_ON_CREATE_WITHOUT_CONFIRMATION_WORKSHOP_SEPARATION_AND_IDEMPOTENCY_PASSED')
